    e: [["chmod 2775 /srv/shared", "общий каталог: все новые файлы получают группу каталога"], ["chmod 1777 /srv/upload", "общий каталог, где нельзя удалять чужие файлы"], ["ls -l /usr/bin/passwd", "-rwsr-xr-x: SUID root"], ["find / -xdev -perm -4000 -type f 2>/dev/null", "аудит SUID-файлов"]],
